	utils "github.com/alibaba/MongoShake/v2/common"
	"github.com/alibaba/MongoShake/v2/oplog"
)

func TestPrometheusHandlerExposesQueueMetrics(t *testing.T) {
	syncer := &OplogSyncer{
		Replset:      "rs-queue-metrics",
		PendingQueue: []chan [][]byte{make(chan [][]byte, 2)},
		logsQueue:    []chan []*oplog.GenericOplog{make(chan []*oplog.GenericOplog, 2)},
	}
	syncer.PendingQueue[0] <- [][]byte{[]byte("a")}
	syncer.logsQueue[0] <- []*oplog.GenericOplog{{}}
	syncer.updatePendingQueueMetric(0)
	syncer.updateLogsQueueMetric(0)

	persister := &Persister{
		replset: syncer.Replset,
		sync:    syncer,
		Buffer:  [][]byte{[]byte("a")},
	}
	persister.updateBufferUsedMetric()

	worker := &Worker{
		syncer: syncer,
		id:     7,
		queue:  make(chan []*oplog.GenericOplog, 2),
	}
	worker.queue <- []*oplog.GenericOplog{{}}
	worker.listUnACK = []*oplog.GenericOplog{{}}
	atomic.StoreInt64(&worker.unackSize, 1)
	worker.updateJobsQueuedMetric()
	worker.updateUnackBufferMetric()

	request := httptest.NewRequest("GET", "/metrics", nil)
	recorder := httptest.NewRecorder()
	utils.PrometheusHandler().ServeHTTP(recorder, request)

	body := recorder.Body.String()
	assert.Equal(t, 200, recorder.Code, "should be equal")
	assert.Contains(t, body, `pending_queue_used{name="rs-queue-metrics",queue_id="0",stage="incr"} 1`, "should be equal")
	assert.Contains(t, body, `logs_queue_used{name="rs-queue-metrics",queue_id="0",stage="incr"} 1`, "should be equal")
	assert.Contains(t, body, `worker_jobs_queued{name="rs-queue-metrics",stage="incr",worker_id="7"} 1`, "should be equal")
	assert.Contains(t, body, `worker_unack_buffer_used{name="rs-queue-metrics",stage="incr",worker_id="7"} 1`, "should be equal")
	assert.Contains(t, body, `persister_buffer_used{name="rs-queue-metrics",stage="incr"} 1`, "should be equal")
}

package collector

import (
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"go.mongodb.org/mongo-driver/bson/primitive"

	utils "github.com/alibaba/MongoShake/v2/common"
	"github.com/alibaba/MongoShake/v2/oplog"
)

func TestObservePutDelayUsesLatestAckedOplog(t *testing.T) {
	now := time.Unix(1_700_000_200, 0).UTC()
	firstTS := now.Add(-20 * time.Second)
	secondTS := now.Add(-30 * time.Second)
	thirdTS := now.Add(-2 * time.Second)
	secondSourceTime := now.Add(-8 * time.Second)

	metric := utils.NewMetric("rs-put-delay", utils.TypeIncr, 0)
	defer metric.Close()

	syncer := &OplogSyncer{
		replMetric: metric,
	}
	worker := &Worker{
		syncer: syncer,
		listUnACK: []*oplog.GenericOplog{
			{
				SourceTime: firstTS,
				Parsed: &oplog.PartialLog{
					ParsedLog: oplog.ParsedLog{
						Timestamp: primitive.Timestamp{T: uint32(firstTS.Unix()), I: 1},
					},
				},
			},
			{
				SourceTime: secondSourceTime,
				Parsed: &oplog.PartialLog{
					ParsedLog: oplog.ParsedLog{
						Timestamp: primitive.Timestamp{T: uint32(secondTS.Unix()), I: 2},
					},
				},
			},
			{
				SourceTime: thirdTS,
				Parsed: &oplog.PartialLog{
					ParsedLog: oplog.ParsedLog{
						Timestamp: primitive.Timestamp{T: uint32(thirdTS.Unix()), I: 3},
					},
				},
			},
		},
	}

	ack := utils.TimeStampToInt64(primitive.Timestamp{T: uint32(secondTS.Unix()), I: 2})
	worker.observePutDelay(ack, now)

	assert.Equal(t, int64(8_000), atomic.LoadInt64(&metric.OplogPutDelay), "should be equal")
}

func TestObservePutDelayFallsBackToTimestamp(t *testing.T) {
	now := time.Unix(1_700_000_260, 0).UTC()
	secondTS := now.Add(-6 * time.Second)

	metric := utils.NewMetric("rs-put-delay-fallback", utils.TypeIncr, 0)
	defer metric.Close()

	worker := &Worker{
		syncer: &OplogSyncer{
			replMetric: metric,
		},
		listUnACK: []*oplog.GenericOplog{
			{
				Parsed: &oplog.PartialLog{
					ParsedLog: oplog.ParsedLog{
						Timestamp: primitive.Timestamp{T: uint32(secondTS.Unix()), I: 2},
					},
				},
			},
		},
	}

	ack := utils.TimeStampToInt64(primitive.Timestamp{T: uint32(secondTS.Unix()), I: 2})
	worker.observePutDelay(ack, now)

	assert.Equal(t, int64(6_000), atomic.LoadInt64(&metric.OplogPutDelay), "should be equal")
}
